import sqlite3
from flask import Flask, g

app = Flask(__name__)
app.config['TESTING'] = True
events = []

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(':memory:')
        events.append('opened')
    return g.db

@app.teardown_appcontext
def close_db(error):
    db = g.pop('db', None)
    if db is not None:
        db.close()
        events.append('closed')

@app.get('/check')
def check():
    first = get_db()
    second = get_db()
    value = first.execute('SELECT 1').fetchone()[0]
    return {'reused': first is second, 'value': value}

client = app.test_client()
print(client.get('/check').json)
print(events)

